target.css:
:root {
  --ink: #18233d;
  --panel: #ffffff;
  --navy: #202c52;
  --muted: #71809b;
  --line: #dce3ef;
  --cyan: #35bfd0;
  --violet: #8668e8;
  --amber: #f2ae47;
  --mint: #43bd91;
  --wash: #f3f7fc;
}

* {
  box-sizing: border-box;
}

.transit-console {
  width: 500px;
  padding: 16px;
  color: var(--ink);
  background: var(--panel);
  border: 1px solid var(--line);
  border-top: 5px solid var(--navy);
  border-radius: 14px;
}

.console-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 13px;
}

.title-block p,
.title-block h1,
.signal-panel p {
  margin: 0;
}

.eyebrow {
  color: var(--muted);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 1.1px;
}

.title-block h1 {
  margin-top: 2px;
  font-size: 22px;
  line-height: 1.1;
  letter-spacing: -0.5px;
}

.live-badge {
  padding: 5px 9px;
  color: var(--mint);
  background: var(--wash);
  border-radius: 999px;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.6px;
}

.console-grid {
  display: grid;
  grid-template-columns: 1.45fr 1fr;
  gap: 12px;
}

.signal-panel {
  margin: 0;
  padding: 12px;
  background: var(--navy);
  border-radius: 10px;
}

.signal-panel figcaption {
  display: flex;
  justify-content: space-between;
  color: var(--panel);
  font-size: 12px;
  font-weight: 700;
}

.signal-panel figcaption strong {
  color: var(--cyan);
  font-size: 11px;
}

.signal-chart {
  display: flex;
  align-items: flex-end;
  height: 59px;
  gap: 5px;
  padding: 8px 2px 4px;
  border-bottom: 1px solid var(--muted);
}

.signal-chart i {
  display: block;
  flex: 1;
  height: 78%;
  background: var(--cyan);
  border-radius: 3px 3px 1px 1px;
}

.signal-chart i:nth-child(2),
.signal-chart i:nth-child(8) {
  height: 63%;
}

.signal-chart i:nth-child(3),
.signal-chart i:nth-child(9) {
  height: 86%;
}

.signal-chart i.dip {
  height: 27%;
  background: var(--amber);
}

.signal-chart i:nth-child(6) {
  height: 39%;
}

.chart-note {
  margin-top: 7px !important;
  color: var(--line);
  font-size: 10px;
}

.readouts {
  display: grid;
  gap: 7px;
}

.reading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 9px 10px;
  background: var(--wash);
  border-left: 4px solid var(--cyan);
  border-radius: 7px;
}

.reading.violet {
  border-left-color: var(--violet);
}

.reading.amber {
  border-left-color: var(--amber);
}

.reading span {
  color: var(--muted);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.5px;
}

.reading strong {
  font-size: 16px;
  letter-spacing: -0.4px;
}

.console-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 12px;
  padding-top: 11px;
  border-top: 1px solid var(--line);
}

.instrument-status {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--muted);
  font-size: 11px;
  font-weight: 700;
}

.status-dot {
  width: 7px;
  height: 7px;
  background: var(--mint);
  border-radius: 50%;
}

button {
  padding: 7px 11px;
  color: var(--panel);
  background: var(--navy);
  border: 0;
  border-radius: 6px;
  font-size: 11px;
  font-weight: 800;
}

